@Service @RequiredArgsConstructor
public class TrainingPlanService {
 private final TrainingPlanRepository plans;private final TrainingPlanExerciseRepository exercises;private final TrainingSessionRepository sessions;
 private final TrainingSessionExerciseRepository sessionExercises;private final TrainingPlanEventRepository events;private final TrainingLookupRepository lookup;
 private final TrainingPlanAccess access;private final MemberRepository members;private final BookingRepository bookings;private final VenueRepository venues;
 private final com.gym.fitness.module.auth.repository.SysUserRepository users;private final EntityManager em;private final ObjectMapper json;
 private Clock businessClock=Clock.system(ZoneId.of("Asia/Shanghai"));
 private LocalDate today(){return LocalDate.now(businessClock);}private LocalDateTime now(){return LocalDateTime.now(businessClock).truncatedTo(ChronoUnit.MICROS);}
 private static BusinessException invalid(String s){return new BusinessException(ErrorCode.PARAM_ERROR,s);}private static BusinessException conflict(String s){return new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED,s);}
 private static void paging(int p,int s){if(p<1||s<1||s>100)throw invalid("分页参数不正确");}
 private static String text(String s,int min,int max,String label){String v=s==null?null:s.trim();if(v==null||v.length()<min||v.length()>max)throw invalid(label+"长度不正确");return v;}
 private static String optional(String s,int max,String label){if(s==null)return null;return text(s,0,max,label);}
 private static void range(Integer n,int min,int max,String name){if(n==null||n<min||n>max)throw invalid(name+"超出允许范围");}
 private static void weight(BigDecimal n){if(n!=null&&(n.signum()<0||n.compareTo(new BigDecimal("500"))>0||Math.max(0,n.stripTrailingZeros().scale())>2))throw invalid("重量应为0至500kg且最多2位小数");}
 private static void values(String mode,Integer sets,Integer reps,BigDecimal kg,Integer minutes){
  if("STRENGTH".equals(mode)){range(sets,1,20,"组数");range(reps,1,200,"次数");weight(kg);if(minutes!=null)throw invalid("力量动作不可填写分钟");}
  else if("DURATION".equals(mode)){range(minutes,1,240,"分钟");if(sets!=null||reps!=null||kg!=null)throw invalid("时长动作不可填写力量数值");}else throw invalid("动作模式不正确");
 }
 private void validatePlan(String title,String goal,LocalDate start,LocalDate end,String note,List<ExerciseInput> input){
  text(title,1,100,"标题");if(!List.of("FAT_LOSS","MUSCLE_GAIN","POSTURE","ENDURANCE","GENERAL").contains(goal==null?"":goal))throw invalid("目标不正确");
  if(start==null||end==null||start.isAfter(end)||ChronoUnit.DAYS.between(start,end)>365||start.isBefore(today().minusDays(365))||end.isAfter(today().plusDays(365)))throw invalid("计划周期不正确");
  optional(note,1000,"备注");if(input==null||input.isEmpty()||input.size()>20)throw invalid("动作须为1至20项");
  for(var e:input){if(e==null)throw invalid("动作不可为空");text(e.name(),1,100,"动作名称");optional(e.note(),300,"动作说明");values(e.mode(),e.sets(),e.reps(),e.weightKg(),e.minutes());}
 }
 private TrainingPlanEntity plan(Long id){if(id==null)throw invalid("计划ID不正确");return plans.findById(id).orElseThrow(TrainingPlanAccess::denied);}
 private MemberEntity lockMember(Long member,SysUserEntity actor){var m=members.findByIdForUpdate(member).orElseThrow(TrainingPlanAccess::denied);em.refresh(m,LockModeType.PESSIMISTIC_WRITE);em.refresh(actor);if(!"ACTIVE".equals(actor.getStatus()))throw TrainingPlanAccess.denied();return m;}
 private static boolean feedbackMemberAllowed(MemberEntity member){return "ACTIVE".equals(member.getStatus())&&!Boolean.TRUE.equals(member.getBlacklistFlag());}
 private static void requireFeedbackMember(MemberEntity member){if(!feedbackMemberAllowed(member))throw TrainingPlanAccess.denied();}
 private void version(Long expected,Long actual){if(expected==null||expected<0)throw invalid("请提供有效版本");if(!expected.equals(actual))throw conflict("资料已更新，请重新加载后操作");}
 private void key(String key){if(key==null||!key.matches("[A-Za-z0-9_-]{8,80}"))throw invalid("请提供8至80位请求标识");}
 // Sort object properties, normalize decimal spellings, and preserve array order. The operation and target IDs are part of the digest.
 private Object canonical(JsonNode n,String property){if(n.isObject()){var m=new TreeMap<String,Object>();n.fields().forEachRemaining(e->m.put(e.getKey(),canonical(e.getValue(),e.getKey())));return m;}if(n.isArray()){var l=new ArrayList<Object>();n.forEach(e->l.add(canonical(e,"")));return l;}if(n.isNumber())return n.decimalValue().stripTrailingZeros();if(n.isNull())return null;if(n.isTextual())return Set.of("title","name","note","reason","content").contains(property)?n.asText().trim():n.asText();return n.asBoolean();}
 private String digest(String type,Long plan,Long session,Object request){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(List.of(type,plan==null?0L:plan,session==null?0L:session,canonical(json.valueToTree(request),"")))));}catch(Exception e){throw new IllegalStateException("无法计算请求摘要",e);}}
 private TrainingPlanEventEntity retry(Long member,SysUserEntity actor,String key,String digest){key(key);var event=events.findByMemberIdAndActorIdAndIdempotencyKey(member,actor.getId(),key).orElse(null);if(event!=null&&!event.getRequestDigest().equals(digest))throw conflict("相同请求标识已用于不同内容");return event;}
 private void event(TrainingPlanEntity p,TrainingSessionEntity s,SysUserEntity a,String type,String reason,String key,String digest){var e=new TrainingPlanEventEntity();e.setMemberId(p.getMemberId());e.setActorId(a.getId());e.setPlanId(p.getId());e.setSessionId(s==null?null:s.getId());e.setType(type);e.setActorName(a.getRealName()==null?a.getUsername():a.getRealName());e.setCreatedAt(now());e.setReason(reason!=null?reason:("RECORD".equals(type)?"训练日期："+s.getPerformedOn()+"，时长："+s.getDurationMinutes()+"分钟":p.getTitle()+"；"+p.getStartDate()+"至"+p.getEndDate()+"；版本："+p.getVersion()));e.setIdempotencyKey(key);e.setRequestDigest(digest);events.saveAndFlush(e);}
 private void content(TrainingPlanEntity p,String title,String goal,LocalDate start,LocalDate end,String note,List<ExerciseInput> input){p.setTitle(title.trim());p.setGoal(goal);p.setStartDate(start);p.setEndDate(end);p.setNote(optional(note,1000,"备注"));p.setUpdatedAt(now());plans.saveAndFlush(p);int position=0;for(var in:input){var e=new TrainingPlanExerciseEntity();e.setPlanId(p.getId());e.setPosition(++position);e.setName(in.name().trim());e.setMode(in.mode());e.setSets(in.sets());e.setReps(in.reps());e.setWeightKg(in.weightKg());e.setMinutes(in.minutes());e.setNote(optional(in.note(),300,"动作说明"));exercises.save(e);}exercises.flush();}
 @Transactional(readOnly=true) public PageView<Student> students(String keyword,int page,int size){paging(page,size);var a=access.actor();if(!access.coach(a))throw TrainingPlanAccess.denied();var found=lookup.students(a.getVenueId(),a.getId(),access.cutoff(),optional(keyword,100,"搜索") == null?"":keyword.trim(),PageRequest.of(page-1,size));return new PageView<>(found.stream().map(m->new Student(m.getId(),m.getRealName(),m.getMemberNo(),m.getVenueId(),m.getTrainingGoal(),m.getTrainingGoalNote())).toList(),found.getTotalElements(),page,size);}
 @Transactional(readOnly=true) public Workbench workbench(Long requested,String status,String keyword,int page,int size,boolean self){
  paging(page,size);if(!List.of("ALL","DRAFT","ACTIVE","ARCHIVED").contains(status))throw invalid("计划状态不正确");var a=access.actor();Long member=self?access.memberId(a):null;Long venue=self?null:access.scope(a,requested);Long coach=!self&&access.coach(a)?a.getId():null;
  String q=optional(keyword,100,"搜索");q=q==null?"":q;var counts=plans.statusCounts(member,venue,coach,access.cutoff());var map=new HashMap<String,Long>();counts.forEach(c->map.put((String)c[0],(Long)c[1]));
  var month=today().withDayOfMonth(1);var summary=new Summary(map.getOrDefault("DRAFT",0L),map.getOrDefault("ACTIVE",0L),map.getOrDefault("ARCHIVED",0L),plans.monthCount(member,venue,coach,access.cutoff(),month,month.plusMonths(1)));
  var found=plans.search(member,venue,coach,access.cutoff(),status,q,PageRequest.of(page-1,size));var opts=!self&&"SUPER_ADMIN".equals(access.role(a))?venues.findAll().stream().map(v->new VenueView(v.getId(),v.getName())).toList():List.<VenueView>of();return new Workbench(summary,new PageView<>(found.stream().map(p->summary(p,a,self)).toList(),found.getTotalElements(),page,size),opts);
 }
 @Transactional(readOnly=true) public Detail detail(Long id,int page,int size,boolean self){paging(page,size);var a=access.actor();var p=plan(id);access.readable(a,p,self);return detail(p,a,page,size,self);}
 private PlanSummary summary(TrainingPlanEntity p,SysUserEntity a,boolean self){var m=members.findById(p.getMemberId()).orElseThrow();var c=users.findById(p.getCoachId()).orElseThrow();var v=venues.findById(p.getVenueId()).orElseThrow();boolean write=!self&&access.canWrite(a,p);var last=sessions.findFirstByPlanIdAndStatusOrderByPerformedOnDescIdDesc(p.getId(),"COMPLETED").orElse(null);return new PlanSummary(p.getId(),p.getMemberId(),m.getRealName(),m.getMemberNo(),p.getCoachId(),c.getRealName(),p.getVenueId(),v.getName(),p.getTitle(),p.getGoal(),p.getStartDate(),p.getEndDate(),p.getNote(),p.getStatus(),p.getVersion(),exercises.countByPlanId(p.getId()),sessions.countByPlanIdAndStatus(p.getId(),"COMPLETED"),last==null?null:last.getPerformedOn(),write&&"DRAFT".equals(p.getStatus()),write&&"DRAFT".equals(p.getStatus()),!self&&access.canArchive(a,p)&&!"ARCHIVED".equals(p.getStatus()),write&&"ACTIVE".equals(p.getStatus()),self||"SUPER_ADMIN".equals(access.role(a))||access.coach(a)||("MANAGER".equals(access.role(a))&&a.getVenueId().equals(m.getVenueId())));}
 private Detail detail(TrainingPlanEntity p,SysUserEntity a,int page,int size,boolean self){
  var targets=exercises.findByPlanIdOrderByPositionAsc(p.getId()).stream().map(e->new ExerciseView(e.getId(),e.getPosition(),e.getName(),e.getMode(),e.getSets(),e.getReps(),e.getWeightKg(),e.getMinutes(),e.getNote())).toList();
  var found=sessions.findByPlanIdOrderByPerformedOnDescIdDesc(p.getId(),PageRequest.of(page-1,size));var ids=found.stream().map(TrainingSessionEntity::getId).toList();var bySession=new HashMap<Long,List<SessionExerciseView>>();
  if(!ids.isEmpty())for(var e:sessionExercises.findBySessionIdInOrderByPositionAsc(ids))bySession.computeIfAbsent(e.getSessionId(),k->new ArrayList<>()).add(new SessionExerciseView(e.getExerciseId(),e.getName(),e.getMode(),e.getPosition(),e.getSets(),e.getReps(),e.getWeightKg(),e.getMinutes(),e.getStatus(),e.getNote(),e.getTargetSets(),e.getTargetReps(),e.getTargetWeightKg(),e.getTargetMinutes()));
  boolean writable=!self&&access.canWrite(a,p);boolean feedbackAllowed=self&&feedbackMemberAllowed(members.findById(p.getMemberId()).orElseThrow(TrainingPlanAccess::denied));var records=found.stream().map(s->new SessionView(s.getId(),p.getId(),s.getVersion(),s.getPerformedOn(),s.getDurationMinutes(),s.getEffort(),s.getNote(),s.getBookingId(),s.getCourseName(),s.getStatus(),s.getVoidReason(),s.getCoachName(),s.getCreatedAt(),s.getFeedbackRating(),s.getFeedbackContent(),s.getFeedbackAt(),writable&&"COMPLETED".equals(s.getStatus()),feedbackAllowed&&"COMPLETED".equals(s.getStatus()),bySession.getOrDefault(s.getId(),List.of()))).toList();
  var audit=self?List.<EventView>of():events.findTop100ByPlanIdOrderByIdDesc(p.getId()).stream().map(e->new EventView(e.getId(),e.getType(),e.getActorName(),e.getCreatedAt(),e.getReason(),e.getSessionId())).toList();return new Detail(summary(p,a,self),targets,new PageView<>(records,found.getTotalElements(),page,size),audit,self?0:events.countByPlanId(p.getId()));
 }
 @Transactional public Detail create(Create r){var a=access.actor();if(!access.related(a,r.memberId()))throw TrainingPlanAccess.denied();lockMember(r.memberId(),a);if(!access.related(a,r.memberId()))throw TrainingPlanAccess.denied();String digest=digest("CREATE",null,null,r);var retry=retry(r.memberId(),a,r.idempotencyKey(),digest);if(retry!=null){var original=plan(retry.getPlanId());em.refresh(original);access.writable(a,original);return detail(original,a,1,20,false);}validatePlan(r.title(),r.goal(),r.startDate(),r.endDate(),r.note(),r.exercises());var p=new TrainingPlanEntity();p.setMemberId(r.memberId());p.setCoachId(a.getId());p.setVenueId(a.getVenueId());p.setStatus("DRAFT");p.setVersion(0L);p.setCreatedAt(now());content(p,r.title(),r.goal(),r.startDate(),r.endDate(),r.note(),r.exercises());event(p,null,a,"CREATE",null,r.idempotencyKey(),digest);return detail(p,a,1,20,false);}
 private TrainingPlanEntity writable(Long id,SysUserEntity a){var p=plan(id);access.writable(a,p);lockMember(p.getMemberId(),a);em.refresh(p);access.writable(a,p);return p;}
 @Transactional public Detail draft(Long id,Draft r){var a=access.actor();var p=writable(id,a);String d=digest("DRAFT",id,null,r);if(retry(p.getMemberId(),a,r.idempotencyKey(),d)!=null)return detail(p,a,1,20,false);version(r.expectedVersion(),p.getVersion());if(!"DRAFT".equals(p.getStatus()))throw conflict("已发布计划内容不可修改");validatePlan(r.title(),r.goal(),r.startDate(),r.endDate(),r.note(),r.exercises());exercises.deleteByPlanId(id);exercises.flush();p.setVersion(p.getVersion()+1);content(p,r.title(),r.goal(),r.startDate(),r.endDate(),r.note(),r.exercises());event(p,null,a,"DRAFT",null,r.idempotencyKey(),d);return detail(p,a,1,20,false);}
 private TrainingPlanEntity archivable(Long id,SysUserEntity a){var p=plan(id);access.archivable(a,p);lockMember(p.getMemberId(),a);em.refresh(p);access.archivable(a,p);return p;}
 @Transactional public Detail transition(Long id,Transition r,boolean publish){var a=access.actor();var p=publish?writable(id,a):archivable(id,a);String type=publish?"PUBLISH":"ARCHIVE";String d=digest(type,id,null,r);if(retry(p.getMemberId(),a,r.idempotencyKey(),d)!=null)return detail(p,a,1,20,false);version(r.expectedVersion(),p.getVersion());String reason=publish?optional(r.reason(),300,"原因"):text(r.reason(),1,300,"归档原因");if(publish){if(!"DRAFT".equals(p.getStatus()))throw conflict("只有草稿可以发布");String active=p.getVenueId()+"/"+p.getMemberId();if(plans.existsByActiveMemberKey(active))throw conflict("该学员在本服务门店已有有效计划，请先归档");p.setActiveMemberKey(active);p.setStatus("ACTIVE");}else{if("ARCHIVED".equals(p.getStatus()))throw conflict("计划已经归档");p.setActiveMemberKey(null);p.setStatus("ARCHIVED");}p.setVersion(p.getVersion()+1);p.setUpdatedAt(now());plans.saveAndFlush(p);event(p,null,a,type,reason,r.idempotencyKey(),d);return detail(p,a,1,20,false);}
 @Transactional(readOnly=true) public List<BookingOption> bookingOptions(Long id,LocalDate performed){var a=access.actor();var p=plan(id);access.writable(a,p);if(performed==null)throw invalid("请提供训练日期");return lookup.options(p.getMemberId(),a.getId(),a.getVenueId(),performed.atStartOfDay(),performed.plusDays(1).atStartOfDay()).stream().filter(b->!sessions.existsByActiveBookingKey(b.getId())).map(b->new BookingOption(b.getId(),b.getSchedule().getCourse().getName(),b.getSchedule().getScheduledStartTime())).toList();}
 @Transactional public Detail record(Long id,RecordSession r){var a=access.actor();var p=writable(id,a);String d=digest("RECORD",id,null,r);if(retry(p.getMemberId(),a,r.idempotencyKey(),d)!=null)return detail(p,a,1,20,false);version(r.expectedVersion(),p.getVersion());if(!"ACTIVE".equals(p.getStatus()))throw conflict("只有有效计划可以登记训练");if(r.performedOn()==null||r.performedOn().isBefore(p.getStartDate())||r.performedOn().isAfter(p.getEndDate())||r.performedOn().isAfter(today())||r.performedOn().isBefore(today().minusDays(365)))throw invalid("训练日期不正确");range(r.durationMinutes(),1,240,"训练时长");if(r.effort()!=null)range(r.effort(),1,10,"主观强度");optional(r.note(),1000,"公开备注");
  var targets=exercises.findByPlanIdOrderByPositionAsc(id);if(r.exercises()==null||r.exercises().size()!=targets.size())throw invalid("必须登记全部计划动作且每个恰好一次");var input=new HashMap<Long,SessionExerciseInput>();boolean done=false;
  for(var e:r.exercises()){if(e==null||e.exerciseId()==null||input.put(e.exerciseId(),e)!=null)throw invalid("动作ID重复或为空");if("DONE".equals(e.status())){done=true;}else if("SKIPPED".equals(e.status())){text(e.note(),1,300,"跳过原因");if(e.sets()!=null||e.reps()!=null||e.weightKg()!=null||e.minutes()!=null)throw invalid("跳过动作不得填写实际数值");}else throw invalid("动作状态不正确");optional(e.note(),300,"动作备注");}
  if(!done)throw invalid("至少完成一个动作");for(var e:targets){var in=input.get(e.getId());if(in==null)throw invalid("包含非计划动作或缺少计划动作");if("DONE".equals(in.status()))values(e.getMode(),in.sets(),in.reps(),in.weightKg(),in.minutes());}
  String courseName=null;if(r.bookingId()!=null){var b=bookings.findById(r.bookingId()).orElseThrow(()->invalid("预约不存在"));em.refresh(b,LockModeType.PESSIMISTIC_READ);var schedule=b.getSchedule();em.refresh(schedule,LockModeType.PESSIMISTIC_READ);if(!b.getMemberId().equals(p.getMemberId())||!a.getId().equals(schedule.getCoachId())||!p.getVenueId().equals(schedule.getVenueId())||!"ATTENDED".equals(b.getStatus())||!schedule.getScheduledStartTime().toLocalDate().equals(r.performedOn()))throw invalid("预约必须为当天该会员本人教练和服务门店的已到课预约");if(sessions.existsByActiveBookingKey(b.getId()))throw conflict("预约已有有效训练记录");courseName=schedule.getCourse().getName();}
  var s=new TrainingSessionEntity();s.setPlanId(id);s.setVersion(0L);s.setPerformedOn(r.performedOn());s.setDurationMinutes(r.durationMinutes());s.setEffort(r.effort());s.setNote(optional(r.note(),1000,"公开备注"));s.setBookingId(r.bookingId());s.setActiveBookingKey(r.bookingId());s.setCourseName(courseName);s.setStatus("COMPLETED");s.setCoachName(a.getRealName()==null?a.getUsername():a.getRealName());s.setCreatedAt(now());sessions.saveAndFlush(s);
  for(var e:targets){var in=input.get(e.getId());var se=new TrainingSessionExerciseEntity();se.setSessionId(s.getId());se.setExerciseId(e.getId());se.setPosition(e.getPosition());se.setName(e.getName());se.setMode(e.getMode());se.setTargetSets(e.getSets());se.setTargetReps(e.getReps());se.setTargetWeightKg(e.getWeightKg());se.setTargetMinutes(e.getMinutes());se.setSets(in.sets());se.setReps(in.reps());se.setWeightKg(in.weightKg());se.setMinutes(in.minutes());se.setStatus(in.status());se.setNote(optional(in.note(),300,"动作备注"));sessionExercises.save(se);}sessionExercises.flush();p.setVersion(p.getVersion()+1);p.setUpdatedAt(now());plans.saveAndFlush(p);event(p,s,a,"RECORD",null,r.idempotencyKey(),d);return detail(p,a,1,20,false);
 }
 private TrainingSessionEntity session(Long id,Long plan){var s=sessions.findById(id).orElseThrow(TrainingPlanAccess::denied);if(!plan.equals(s.getPlanId()))throw TrainingPlanAccess.denied();em.refresh(s);return s;}
 @Transactional public Detail voidSession(Long id,Long sid,Transition r){var a=access.actor();var p=writable(id,a);var s=session(sid,id);String d=digest("VOID",id,sid,r);if(retry(p.getMemberId(),a,r.idempotencyKey(),d)!=null)return detail(p,a,1,20,false);version(r.expectedVersion(),s.getVersion());String reason=text(r.reason(),1,300,"作废原因");if(!"COMPLETED".equals(s.getStatus()))throw conflict("记录已经作废");s.setStatus("VOIDED");s.setVoidReason(reason);s.setActiveBookingKey(null);s.setVersion(s.getVersion()+1);sessions.saveAndFlush(s);event(p,s,a,"VOID",reason,r.idempotencyKey(),d);return detail(p,a,1,20,false);}
 @Transactional public Detail feedback(Long id,Long sid,Feedback r){var a=access.actor();var p=plan(id);access.readable(a,p,true);requireFeedbackMember(members.findById(p.getMemberId()).orElseThrow(TrainingPlanAccess::denied));var lockedMember=lockMember(p.getMemberId(),a);requireFeedbackMember(lockedMember);em.refresh(p);access.readable(a,p,true);var s=session(sid,id);String d=digest("FEEDBACK",id,sid,r);if(retry(p.getMemberId(),a,r.idempotencyKey(),d)!=null)return detail(p,a,1,20,true);version(r.expectedVersion(),s.getVersion());if(!"COMPLETED".equals(s.getStatus()))throw conflict("作废记录不可反馈");range(r.rating(),1,5,"反馈评分");String content=optional(r.content(),500,"反馈内容");s.setFeedbackRating(r.rating());s.setFeedbackContent(content);s.setFeedbackAt(now());s.setVersion(s.getVersion()+1);sessions.saveAndFlush(s);event(p,s,a,"FEEDBACK","评分"+r.rating()+(content==null?"":"："+content),r.idempotencyKey(),d);return detail(p,a,1,20,true);}
}
